p='src/components/report/lists.tsx'
s=open(p).read()
old=s[s.index('/** The rows in the order of a sort'):s.index('const nextSort')]
new='''/** The rows in the order of a sort ("severity", "-id"), or the usual order when there is none. Rows without a value
 * (no severity, no product) stay last either way; ties keep the usual order. */
export function sortRows(model: Model, rows: Row[], sort: string) {
  const usual = sortTests(rows)
  const key = sort.replace(/^-/, "")
  const text = (a: string, b: string) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" })
  const columns: Record<string, { value: (t: Row) => string; compare: (a: string, b: string) => number }> = {
    result: { value: (t) => t.Result, compare: (a, b) => rank(RESULT_ORDER, a) - rank(RESULT_ORDER, b) },
    id: { value: (t) => t.Id, compare: (a, b) => a.localeCompare(b, undefined, { numeric: true }) },
    product: { value: (t) => (t.Product ? model.productName(t.Product) : ""), compare: text },
    severity: { value: (t) => (SEVERITIES.includes(t.Severity) ? t.Severity : ""), compare: (a, b) => rank(SEVERITIES, a) - rank(SEVERITIES, b) },
    source: { value: (t) => sourceLabel(model, t), compare: text },
  }
  const column = columns[key]
  if (!column) return usual
  const dir = sort.startsWith("-") ? -1 : 1
  return usual.sort((a, b) => {
    const x = column.value(a), y = column.value(b)
    return !x || !y ? Number(!x) - Number(!y) : dir * column.compare(x, y)
  })
}

'''
s=s.replace(old,new)
open(p,'w').write(s)
EOF
