1	// The filters of the test catalog, shared by the nav (CatalogNav.astro) and the list on the page (CatalogList.astro).
2	// The URL is the state: each filter is a query parameter with comma-separated values, so a filtered view can be
3	// shared and survives a reload. A change is announced with a `mt-catalog` event on window.
4	
5	export const FILTERS = ['q', 'severity', 'area', 'cost', 'impact', 'source', 'channel', 'product', 'feature', 'suite', 'mitre', 'pillar', 'author', 'group', 'sort'] as const;
6	export type Filter = (typeof FILTERS)[number];
7	export type State = Record<Filter, string[]>;
8	
9	// How the list is shown rather than which checks it holds: kept when the filters are cleared.
10	export const VIEW: readonly Filter[] = ['group', 'sort'];
11	
12	export function readState(): State {
13		const params = new URLSearchParams(location.search);
14		const state = {} as State;
15		for (const name of FILTERS) {
16			const value = params.get(name) ?? '';
17			// eslint-disable-next-line security/detect-object-injection -- name is one of FILTERS
18			state[name] = name === 'q' ? (value ? [value] : []) : value.split(',').filter(Boolean);
19		}
