await new Promise(r=>setTimeout(r,2500));
const t = document.querySelector('[data-table]'); const vis = (el) => getComputedStyle(el).display !== 'none';
const out = { show: t.dataset.show, cols: t.style.getPropertyValue('--mt-cl-cols'), head: [...document.querySelectorAll('.mt-cl__head [data-sort]')].filter(vis).map(b=>b.textContent.replace(/[▲▼↕]/g,'').trim()) };
const menu = document.querySelector('[data-cols-menu]'); menu.querySelector('summary').click(); await new Promise(r=>setTimeout(r,100));
out.open = menu.open; out.opts = [...menu.querySelectorAll('label')].map(l=>l.textContent.trim()+(l.querySelector('input').checked?' ✓':''));
for (const k of ['area','cost','mitre','control','source']) menu.querySelector(`[data-col-toggle="${k}"]`).click();
await new Promise(r=>setTimeout(r,100));
out.head2 = [...document.querySelectorAll('.mt-cl__head [data-sort]')].filter(vis).map(b=>b.textContent.replace(/[▲▼↕]/g,'').trim());
const row = document.querySelector('.mt-cl__row:not([hidden])'); out.row = [...row.children].filter(vis).map(c=>c.textContent.trim().slice(0,30));
out.saved = localStorage.getItem('maester.catalog.columns'); out.min = t.style.getPropertyValue('--mt-cl-min');
document.querySelector('[data-sort="cost"]').click(); await new Promise(r=>setTimeout(r,150));
out.costSorted = [...new Set([...document.querySelectorAll('.mt-cl__row')].filter(r=>!r.hidden).map(r=>r.dataset.cost))];
document.body.click(); out.closed = !menu.open; out

